# Bám sách: trang 86–87 + đáp án + Mini dictionary unit 41. Không chép nguyên văn.
theory = (
 H("A", "Phrasal verbs connected with feelings", "Phrasal verb về cảm xúc")
 + P("Phoebe emails her friend Francesca about her problems in the band she sings with; Francesca replies.", "Phoebe gửi email cho bạn là Francesca kể chuyện khó khăn trong ban nhạc mình hát; Francesca trả lời.")
 + T([
    ("<b>summon up</b>", "Phoebe can hardly find the energy, even with great effort, to get up in the morning.", "Phoebe khó mà gom nổi sức để dậy mỗi sáng."),
    ("<b>go off</b> / <b>not care for</b>", "(UK, Aus) She may have stopped liking the idea of a singing career, or she simply dislikes the band’s current music.", "(Anh, Úc) Có thể cô đã hết thích ý định làm ca sĩ, hoặc chỉ là không thích loại nhạc ban đang chơi."),
    ("<b>have</b> sth <b>against</b> / <b>turn</b> sb <b>against</b>", "She thinks the band leader dislikes her for some reason and is making the other members dislike her too.", "Cô nghĩ trưởng nhóm có ác cảm với mình vì lý do nào đó và đang khiến các thành viên khác cũng ghét mình."),
    ("<b>loosen up</b> / <b>work yourself into</b>", "She knows she must relax mentally and not make herself very upset about it.", "Cô biết mình phải thả lỏng đầu óc và đừng tự làm mình rối lên vì chuyện này."),
    ("<b>snap out of</b> / <b>give in to</b>", "(informal) Francesca says Phoebe can force herself to stop feeling low, and must not let negative thoughts control her.", "(thân mật) Francesca bảo Phoebe có thể tự dứt ra khỏi nỗi buồn và đừng để suy nghĩ tiêu cực chi phối."),
    ("<b>hanker after</b>", "Francesca thinks Phoebe secretly wants a change very much.", "Francesca nghĩ Phoebe thầm khao khát một sự thay đổi."),
    ("<b>perk up</b> / <b>brim with</b>", "If she leaves the band, she will soon become happier and be full of enthusiasm again.", "Nếu rời ban nhạc, cô sẽ sớm vui lên và lại tràn đầy hào hứng."),
 ])
 + H("B", "Paraphrasing feelings with phrasal verbs", "Diễn đạt lại cảm xúc bằng phrasal verb")
 + P("In short dialogues, the second speaker repeats what the first one said, using a phrasal verb.", "Trong các đoạn hội thoại ngắn, người nói thứ hai nhắc lại ý người thứ nhất bằng một phrasal verb.")
 + T([
    ("<b>choke back</b> / <b>fight back</b>", "Bella was very angry and close to tears: she forced herself not to show her anger and tried hard not to cry.", "Bella rất giận và suýt khóc: cô cố nén giận và cố kìm nước mắt."),
    ("<b>bowl over</b>", "Armand was very surprised and pleased by everyone’s generous leaving gift.", "Armand rất bất ngờ và cảm động trước món quà chia tay hào phóng của mọi người."),
    ("<b>spill out</b>", "Molly suddenly talked about her emotions without being able to stop.", "Molly bỗng tuôn ra hết cảm xúc, không dừng lại được."),
    ("<b>feel up to</b>", "After a cold, Rosie did not feel strong enough in body and mind for a long meeting.", "Sau trận cảm, Rosie không thấy đủ sức khỏe và tinh thần cho một cuộc họp dài."),
    ("<b>go out to</b>", "Isaac’s mother has died; Natalie feels very sorry for him and his family.", "Mẹ Isaac mất; Natalie rất thương cảm anh và gia đình."),
    ("<b>shake up</b>", "The news shocked Imogen and upset her badly.", "Tin đó làm Imogen bàng hoàng và rất buồn."),
    ("<b>come over</b>", "At the War Memorial, everyone suddenly felt a strong sadness.", "Ở Đài tưởng niệm chiến tranh, mọi người bỗng thấy buồn da diết."),
    ("<b>run away with</b>", "We must stay calm and not let our emotions push us into something stupid.", "Ta phải bình tĩnh, không để cảm xúc đẩy mình làm điều dại dột."),
 ])
 + NOTE("<b>From the exercises</b>: <b>choke back</b> and <b>fight back</b> are both possible with anger, tears and disappointment; <b>brim with</b> goes with excitement, enthusiasm and self-confidence; you can be <b>bowled over</b> by someone’s charm, beauty or generosity.",
        "<b>Từ bài tập</b>: <b>choke back</b> và <b>fight back</b> đều dùng được với giận dữ, nước mắt, thất vọng; <b>brim with</b> đi với hào hứng, nhiệt tình, tự tin; có thể <b>bowled over</b> trước sức quyến rũ, vẻ đẹp hay sự hào phóng của ai.")
)
